package com.himanshu.liftly.core.data.seed

import com.himanshu.liftly.core.domain.model.Difficulty
import com.himanshu.liftly.core.domain.model.Equipment
import com.himanshu.liftly.core.domain.model.Mechanic
import com.himanshu.liftly.core.domain.model.Muscle
import com.himanshu.liftly.core.domain.model.TrackingType
import kotlinx.serialization.Serializable

/** Format of `files/exercises.json` (generated by tools/seed/build_seed.py). */
@Serializable
data class SeedFile(val version: Int, val exercises: List<SeedExercise>)

@Serializable
data class SeedExercise(
    val seedKey: String,
    val name: String,
    val aliases: List<String> = emptyList(),
    val primaryMuscle: Muscle,
    val secondaryMuscles: List<Muscle> = emptyList(),
    val equipment: Equipment,
    val trackingType: TrackingType,
    val mechanic: Mechanic? = null,
    val difficulty: Difficulty? = null,
    val imagePaths: List<String> = emptyList(),
    val videoUrl: String? = null,
    val instructions: List<String> = emptyList(),
    val formCues: List<String> = emptyList(),
    val commonMistakes: List<String> = emptyList(),
)

/** Supplies the raw seed JSON; implemented where the bundled resources live. */
fun interface SeedSource {
    suspend fun readExercisesJson(): String
}
